    price numeric(38, 2),
    rating_count integer,
    view_count integer,
    weather_sensitive boolean,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    category_id uuid,
    id uuid NOT NULL,
    vendor_id uuid,
    address character varying(255) COLLATE pg_catalog."default",
    description character varying(255) COLLATE pg_catalog."default",
    description_en character varying(255) COLLATE pg_catalog."default",
    location_name character varying(255) COLLATE pg_catalog."default",
    name character varying(255) COLLATE pg_catalog."default",
    name_en character varying(255) COLLATE pg_catalog."default",
    rejection_reason character varying(255) COLLATE pg_catalog."default",
