    waiver_content_en text COLLATE pg_catalog."default",
    search_vector tsvector GENERATED ALWAYS AS ((((setweight(to_tsvector('simple'::regconfig, (COALESCE(name, ''::character varying))::text), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, (COALESCE(name_en, ''::character varying))::text), 'A'::"char")) || setweight(to_tsvector('simple'::regconfig, (COALESCE(description, ''::character varying))::text), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, (COALESCE(description_en, ''::character varying))::text), 'B'::"char"))) STORED,
